const listSignupRequests = `-- name: ListSignupRequests :many
SELECT id, org_id, email, name, username, note, status, email_verified_at, code_salt, code_hash, code_attempts, code_attempts_total, code_expires_at, created_at, expires_at, decided_at, decided_by, user_id, reject_reason, blocked FROM signup_requests
WHERE org_id = $1 AND ($3::text IS NULL OR status = $3::text)
  AND NOT ($4::boolean AND status = 'pending' AND email_verified_at IS NULL AND code_hash IS NOT NULL)
ORDER BY created_at DESC, id DESC
LIMIT $2
`

type ListSignupRequestsParams struct {
	OrgID          uuid.UUID
	Limit          int32
	Status         *string
	HideUnverified bool
}

// scope: admin
// hide_unverified: leave out pending requests that wait for their confirm
// code (unverified, with a code): while mail works, such a request shows
// only after the proof. A request made while mail was off has no code and
// stays visible.
func (q *Queries) ListSignupRequests(ctx context.Context, arg ListSignupRequestsParams) ([]SignupRequest, error) {
	rows, err := q.db.Query(ctx, listSignupRequests,
		arg.OrgID,
		arg.Limit,
		arg.Status,
		arg.HideUnverified,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SignupRequest{}
	for rows.Next() {
		var i SignupRequest
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.Email,
			&i.Name,
			&i.Username,
			&i.Note,
			&i.Status,
			&i.EmailVerifiedAt,
			&i.CodeSalt,
			&i.CodeHash,
			&i.CodeAttempts,
			&i.CodeAttemptsTotal,
			&i.CodeExpiresAt,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.DecidedAt,
			&i.DecidedBy,
			&i.UserID,
			&i.RejectReason,
			&i.Blocked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockInviteTeamsForAccept = `-- name: LockInviteTeamsForAccept :many
SELECT t.id
FROM org_invite_teams it
JOIN teams t ON t.org_id = it.org_id AND t.id = it.team_id
WHERE it.org_id = $1 AND it.invite_id = $2
ORDER BY t.id
FOR KEY SHARE OF t
`

type LockInviteTeamsForAcceptParams struct {
	OrgID    uuid.UUID
	InviteID uuid.UUID
}

// scope: system
// The teams of a 'selected' invite that still exist, locked against a
// concurrent team delete for the rest of the accept (#27). A team deleted
// before is gone by the cascade; one deleted while this waits is skipped.
func (q *Queries) LockInviteTeamsForAccept(ctx context.Context, arg LockInviteTeamsForAcceptParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockInviteTeamsForAccept, arg.OrgID, arg.InviteID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

