const setSignupCode = `-- name: SetSignupCode :exec
UPDATE signup_requests
SET code_salt = $2, code_hash = $3, code_attempts = 0,
    code_expires_at = now() + make_interval(secs => $4::double precision),
    expires_at = least(expires_at, now() + make_interval(secs => $5::double precision))
WHERE id = $1 AND status = 'pending' AND email_verified_at IS NULL
`

type SetSignupCodeParams struct {
	ID                    uuid.UUID
	CodeSalt              []byte
	CodeHash              []byte
	TtlSeconds            float64
	UnconfirmedTtlSeconds float64
}

// scope: system
// A new confirm code replaces the open one. code_attempts (this code's
// wrong tries) starts again; code_attempts_total does not. An unconfirmed
// request lives at most unconfirmed_ttl from now (never longer than it
// had), so asking again does not keep it alive.
func (q *Queries) SetSignupCode(ctx context.Context, arg SetSignupCodeParams) error {
	_, err := q.db.Exec(ctx, setSignupCode,
		arg.ID,
		arg.CodeSalt,
		arg.CodeHash,
		arg.TtlSeconds,
		arg.UnconfirmedTtlSeconds,
	)
	return err
}

